import { lazy } from 'react';

// ----------------------------------------------------------------------

const PayrollAndAllowancesPage = lazy(() => import('../pages/PayrollAndAllowances.page'));
const AddAllowancePage = lazy(() => import('../pages/AddAllowance.page'));

// ----------------------------------------------------------------------

const PayrollRoutes = [
    {
        path: '/payroll',
        element: <PayrollAndAllowancesPage />,
        layout: 'default',
        isAuthReq: true,
    },
    {
        path: '/payroll-allowances/add-allowance',
        element: <AddAllowancePage />,
        layout: 'default',
        isAuthReq: true,
    },
];

export { PayrollRoutes };
